// A GRANTED third-party package (holds fs:read). It does real async work of its
// own — the case a naive "deny any single-principal deputy-class op" fix would
// FALSE-DENY. Two shapes:
//   readOwnAsync       — reads in its OWN microtask continuation. The scheduler
//                        (logger) equals the running principal, so the collected
//                        stack collapses to [logger] and the read is allowed.
//   readViaDeputyAsync — drives the deputy across a microtask. Both principals in
//                        the causal chain (logger scheduler + deputy) are granted,
//                        so the deputy-class AND passes.
// @ref LLP 0013#phase-5
var fs = require("fs");
var deputy = require("deputy-pkg");
module.exports.readOwnAsync = function readOwnAsync(path) {
  return Promise.resolve(path).then(function (p) {
    return String(fs.readFileSync(p)).trim();
  });
};
module.exports.readViaDeputyAsync = function readViaDeputyAsync(path) {
  return Promise.resolve(path).then(deputy.readFor);
};
